var opt = new SpatialElementBoundaryOptions(); opt.SpatialElementBoundaryLocation = SpatialElementBoundaryLocation.Finish;
var res = new List<object>();
foreach (var r in new FilteredElementCollector(doc).OfCategory(BuiltInCategory.OST_Rooms).Cast<Autodesk.Revit.DB.Architecture.Room>()) {
  var segs = new List<object>();
  foreach (var loop in r.GetBoundarySegments(opt)) foreach (var s in loop) {
    var c = s.GetCurve(); var e = doc.GetElement(s.ElementId);
    segs.Add(new { el = s.ElementId.IntegerValue, cat = e==null?null:e.Category?.Name, type = e==null?null:e.Name, len = Math.Round(c.Length*0.3048,3),
      x0=Math.Round(c.GetEndPoint(0).X*0.3048,3), y0=Math.Round(c.GetEndPoint(0).Y*0.3048,3), x1=Math.Round(c.GetEndPoint(1).X*0.3048,3), y1=Math.Round(c.GetEndPoint(1).Y*0.3048,3)});
  }
  res.Add(new { r.Name, segs });
}
return res;
